 20→#endif
 21→
 22→
 23→UBridgeComponent::UBridgeComponent()
 24→{
 25→    PrimaryComponentTick.bCanEverTick = true;
 26→
 27→    // Default path: ~/.translators on Windows/Linux/Mac
 28→    BridgePath = FPaths::Combine(FPlatformProcess::UserHomeDir(), TEXT(".translators"));
 29→}
 30→
 31→
 32→void UBridgeComponent::BeginPlay()
 33→{
 34→    Super::BeginPlay();
 35→
 36→    BridgeLog(TEXT("========================================"));
 37→    BridgeLog(TEXT("TRANSLATORS BRIDGE COMPONENT v2.0.0"));
 38→    BridgeLog(TEXT("USD-native communication with JSON fallback"));
 39→    BridgeLog(FString::Printf(TEXT("Bridge Path: %s"), *BridgePath));
 40→    BridgeLog(TEXT("========================================"));
 41→
 42→    // Ensure bridge directory exists
 43→    IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
 44→    if (!PlatformFile.DirectoryExists(*BridgePath))
 45→    {
 46→        PlatformFile.CreateDirectory(*BridgePath);
 47→        BridgeLog(FString::Printf(TEXT("Created bridge directory: %s"), *BridgePath));
 48→    }
 49→
 50→    SetupFileWatcher();
 51→
 52→    // Check for existing state files (Claude Code may have started first)
 53→    // Prefer USD over JSON
 54→    FString UsdFilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
 55→    FString JsonFilePath = GetBridgeFilePath(TEXT("state.json"));
 56→
 57→    if (PlatformFile.FileExists(*UsdFilePath))
 58→    {
 59→        BridgeLog(TEXT("Found existing bridge_state.usda - processing..."));
 60→        ProcessStateFile();
 61→    }
 62→    else if (PlatformFile.FileExists(*JsonFilePath))
 63→    {
 64→        BridgeLog(TEXT("Found existing state.json - processing..."));
 65→        ProcessStateFile();
 66→    }
 67→}
 68→
 69→
 70→void UBridgeComponent::EndPlay(const EEndPlayReason::Type EndPlayReason)
 71→{
 72→    TeardownFileWatcher();
 73→
 74→    BridgeLog(TEXT("TRANSLATORS BRIDGE COMPONENT STOPPED"));
 75→
 76→    Super::EndPlay(EndPlayReason);
 77→}
 78→
 79→
 80→void UBridgeComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
 81→{
 82→    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);
 83→
 84→    // Polling fallback for non-editor builds
 85→    if (bUsePolling)
 86→    {
 87→        PollTimer += DeltaTime;
 88→        if (PollTimer >= PollInterval)
 89→        {
 90→            PollTimer = 0.0f;
 91→
 92→            FString StateFilePath = GetBridgeFilePath(TEXT("state.json"));
 93→            IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
 94→
 95→            if (PlatformFile.FileExists(*StateFilePath))
 96→            {
 97→                FDateTime ModTime = PlatformFile.GetTimeStamp(*StateFilePath);
 98→                if (ModTime > LastStateFileTime)
 99→                {
100→                    LastStateFileTime = ModTime;
101→                    bStateChangePending = true;
102→                    TimeSinceLastStateChange = 0.0f;
103→                }
104→            }
105→        }
106→    }
107→
108→    // Debounced state file processing
109→    if (bStateChangePending)
110→    {
111→        TimeSinceLastStateChange += DeltaTime;
112→        if (TimeSinceLastStateChange >= DebounceTime)
113→        {
114→            bStateChangePending = false;
115→            ProcessStateFile();
116→        }
117→    }
118→
119→    // Debounced USD file processing
120→    if (bUsdChangePending)
121→    {
122→        TimeSinceLastUsdChange += DeltaTime;
123→        if (TimeSinceLastUsdChange >= DebounceTime)
124→        {
125→            bUsdChangePending = false;
126→            OnUsdFileChanged();
127→        }
128→    }
129→}
