132→// === FILE WATCHING ===
133→
134→void UBridgeComponent::SetupFileWatcher()
135→{
136→#if WITH_DIRECTORY_WATCHER
137→    FDirectoryWatcherModule& DirWatcherModule =
138→        FModuleManager::LoadModuleChecked<FDirectoryWatcherModule>(TEXT("DirectoryWatcher"));
139→    IDirectoryWatcher* DirWatcher = DirWatcherModule.Get();
140→
141→    if (!DirWatcher)
142→    {
143→        BridgeLog(TEXT("ERROR: Could not get DirectoryWatcher module"));
144→        return;
145→    }
146→
147→    IDirectoryWatcher::FDirectoryChanged Callback =
148→        IDirectoryWatcher::FDirectoryChanged::CreateUObject(
149→            this, &UBridgeComponent::OnDirectoryChanged);
150→
151→    uint32 WatchFlags = 0; // No special flags needed
152→
153→    bool bSuccess = DirWatcher->RegisterDirectoryChangedCallback_Handle(
154→        BridgePath, Callback, WatchHandle, WatchFlags);
155→
156→    if (bSuccess)
157→    {
158→        BridgeLog(FString::Printf(TEXT("File watcher registered for: %s"), *BridgePath));
159→    }
160→    else
161→    {
162→        BridgeLog(TEXT("ERROR: Failed to register file watcher"));
163→    }
164→#else
165→    // Non-editor: Use polling in TickComponent
166→    BridgeLog(TEXT("DirectoryWatcher not available - using file polling"));
167→    bUsePolling = true;
168→#endif
169→}
170→
171→
172→void UBridgeComponent::TeardownFileWatcher()
173→{
174→#if WITH_DIRECTORY_WATCHER
175→    if (WatchHandle.IsValid())
176→    {
177→        FDirectoryWatcherModule& DirWatcherModule =
178→            FModuleManager::LoadModuleChecked<FDirectoryWatcherModule>(TEXT("DirectoryWatcher"));
179→        IDirectoryWatcher* DirWatcher = DirWatcherModule.Get();
180→
181→        if (DirWatcher)
182→        {
183→            DirWatcher->UnregisterDirectoryChangedCallback_Handle(BridgePath, WatchHandle);
184→            BridgeLog(TEXT("File watcher unregistered"));
185→        }
186→    }
187→#endif
188→}
189→
190→
191→#if WITH_DIRECTORY_WATCHER
192→void UBridgeComponent::OnDirectoryChanged(const TArray<FFileChangeData>& Changes)
193→{
194→    for (const FFileChangeData& Change : Changes)
195→    {
196→        if (bVerboseLogging)
197→        {
198→            BridgeLog(FString::Printf(TEXT("File changed: %s"), *Change.Filename));
199→        }
200→
201→        // State file changes (JSON or USD bridge state)
202→        if (Change.Filename.EndsWith(TEXT("state.json")) ||
203→            Change.Filename.EndsWith(TEXT("bridge_state.usda")))
204→        {
205→            // Debounce state file changes
206→            TimeSinceLastStateChange = 0.0f;
207→            bStateChangePending = true;
208→        }
209→        // USD cognitive profile changes (separate from bridge state)
210→        else if (Change.Filename.EndsWith(TEXT("cognitive_profile.usda")) ||
211→                 Change.Filename.EndsWith(TEXT("cognitive_substrate.usda")))
212→        {
213→            // Debounce USD profile file changes
214→            TimeSinceLastUsdChange = 0.0f;
215→            bUsdChangePending = true;
216→        }
217→    }
218→}
219→#endif
220→
221→
222→// === STATE HANDLING ===
223→
224→void UBridgeComponent::ProcessStateFile()
225→{
226→    // Try USD mode first (v2.0.0)
227→    FString UsdFilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
228→    IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
229→
230→    if (PlatformFile.FileExists(*UsdFilePath))
231→    {
232→        if (ProcessBridgeStateUsda())
233→        {
234→            return; // Successfully processed USD
235→        }
236→    }
237→
238→    // Fall back to JSON mode (v1.0.0)
239→    FString FilePath = GetBridgeFilePath(TEXT("state.json"));
240→    FString Content;
241→
242→    if (!FFileHelper::LoadFileToString(Content, *FilePath))
243→    {
244→        if (bVerboseLogging)
245→        {
246→            BridgeLog(TEXT("Could not read state.json or bridge_state.usda"));
247→        }
248→        return;
249→    }
250→
251→    // Parse JSON
252→    TSharedPtr<FJsonObject> JsonObj;
253→    TSharedRef<TJsonReader<>> Reader = TJsonReaderFactory<>::Create(Content);
254→
255→    if (!FJsonSerializer::Deserialize(Reader, JsonObj) || !JsonObj.IsValid())
256→    {
257→        BridgeLog(TEXT("ERROR: Invalid JSON in state.json"));
258→        return;
259→    }
260→
261→    CurrentStateJson = Content;
262→    bUsingUsdMode = false;
263→
264→    // Route by type
265→    FString StateType;
