440→void UBridgeComponent::WriteJsonToFile(const FString& Filename, const TSharedPtr<FJsonObject>& JsonObj)
441→{
442→    FString FilePath = GetBridgeFilePath(Filename);
443→    FString OutputString;
444→
445→    TSharedRef<TJsonWriter<>> Writer = TJsonWriterFactory<>::Create(&OutputString);
446→    FJsonSerializer::Serialize(JsonObj.ToSharedRef(), Writer);
447→
448→    // Write with retry logic (file may be locked by Claude Code reading it)
449→    int32 MaxRetries = 3;
450→    for (int32 Retry = 0; Retry < MaxRetries; ++Retry)
451→    {
452→        if (FFileHelper::SaveStringToFile(OutputString, *FilePath))
453→        {
454→            return; // Success
455→        }
456→
457→        if (Retry < MaxRetries - 1)
458→        {
459→            BridgeLog(FString::Printf(TEXT("Write failed, retry %d/%d..."), Retry + 1, MaxRetries));
460→            FPlatformProcess::Sleep(0.1f);
461→        }
462→    }
463→
464→    BridgeLog(FString::Printf(TEXT("ERROR: Failed to write %s after %d retries"), *Filename, MaxRetries));
465→}
