530→FString UBridgeComponent::ParseUsdaVariant(const FString& Content, const FString& VariantSetName)
531→{
532→    // Parse variant selection from: variants = { string variantName = "value" }
533→    FString Pattern = FString::Printf(TEXT("string %s = \"([^\"]*)\""), *VariantSetName);
534→    FRegexPattern RegexPattern(Pattern);
535→    FRegexMatcher Matcher(RegexPattern, Content);
536→
537→    if (Matcher.FindNext())
538→    {
539→        return Matcher.GetCaptureGroup(1);
540→    }
541→    return TEXT("");
542→}
