544→
545→FString UBridgeComponent::ParseUsdaAttribute(const FString& Content, const FString& PrimPath, const FString& AttrName)
546→{
547→    // Find the prim section and extract attribute value
548→    // This is a simplified parser - handles basic string/int/float attributes
549→
550→    // First find the prim section
551→    FString PrimPattern = FString::Printf(TEXT("def [^\"]*\"%s\"[^{]*\\{([^}]*)\\}"), *PrimPath);
552→    FRegexPattern PrimRegex(PrimPattern);
553→    FRegexMatcher PrimMatcher(PrimRegex, Content);
554→
555→    FString PrimContent;
556→    if (PrimMatcher.FindNext())
557→    {
558→        PrimContent = PrimMatcher.GetCaptureGroup(1);
559→    }
560→    else
561→    {
562→        // Try finding nested prim
563→        PrimContent = Content;
564→    }
565→
566→    // Parse string attribute
567→    FString StringPattern = FString::Printf(TEXT("string %s = \"([^\"]*)\""), *AttrName);
568→    FRegexPattern StringRegex(StringPattern);
569→    FRegexMatcher StringMatcher(StringRegex, PrimContent);
570→    if (StringMatcher.FindNext())
571→    {
572→        return StringMatcher.GetCaptureGroup(1);
573→    }
574→
575→    // Parse int attribute
576→    FString IntPattern = FString::Printf(TEXT("int %s = (-?\\d+)"), *AttrName);
577→    FRegexPattern IntRegex(IntPattern);
578→    FRegexMatcher IntMatcher(IntRegex, PrimContent);
579→    if (IntMatcher.FindNext())
580→    {
581→        return IntMatcher.GetCaptureGroup(1);
582→    }
583→
584→    // Parse float/double attribute
585→    FString FloatPattern = FString::Printf(TEXT("(?:float|double) %s = ([\\d.]+)"), *AttrName);
586→    FRegexPattern FloatRegex(FloatPattern);
587→    FRegexMatcher FloatMatcher(FloatRegex, PrimContent);
588→    if (FloatMatcher.FindNext())
589→    {
590→        return FloatMatcher.GetCaptureGroup(1);
591→    }
592→
593→    return TEXT("");
594→}
