700→void UBridgeComponent::SendAnswerUsda(const FString& QuestionId, int32 OptionIndex, float ResponseTimeMs)
701→{
702→    FString FilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
703→    FString Content;
704→
705→    if (!FFileHelper::LoadFileToString(Content, *FilePath))
706→    {
707→        BridgeLog(TEXT("ERROR: Could not read bridge_state.usda for answer"));
708→        // Fall back to JSON
709→        SendAnswer(QuestionId, OptionIndex, ResponseTimeMs);
710→        return;
711→    }
712→
713→    FString Timestamp = FDateTime::UtcNow().ToIso8601();
714→    FString SelectedLabel = (OptionIndex >= 0 && OptionIndex < CurrentQuestion.OptionLabels.Num())
715→        ? CurrentQuestion.OptionLabels[OptionIndex] : TEXT("");
716→    FString SelectedDirection = (OptionIndex >= 0 && OptionIndex < CurrentQuestion.OptionDirections.Num())
717→        ? CurrentQuestion.OptionDirections[OptionIndex] : TEXT("");
718→
719→    // Update sync_status variant to "answer_received"
720→    Content = UpdateUsdaVariant(Content, TEXT("sync_status"), TEXT("answer_received"));
721→    Content = UpdateUsdaVariant(Content, TEXT("message_type"), TEXT("answer"));
722→
723→    // Update Answer prim attributes
724→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("question_id"), QuestionId, true);
725→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("option_index"), FString::FromInt(OptionIndex), false);
726→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("response_time_ms"), FString::SanitizeFloat(ResponseTimeMs), false);
727→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("selected_label"), SelectedLabel, true);
728→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("selected_direction"), SelectedDirection, true);
729→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("timestamp"), Timestamp, true);
730→
731→    // Update behavioral signals
732→    UpdateBehavioralSignals(Content, ResponseTimeMs);
733→
734→    // Write back
735→    int32 MaxRetries = 3;
736→    for (int32 Retry = 0; Retry < MaxRetries; ++Retry)
737→    {
738→        if (FFileHelper::SaveStringToFile(Content, *FilePath))
739→        {
740→            BridgeLog(FString::Printf(TEXT("USD answer sent: %s = option %d (%.0fms)"),
741→                *QuestionId, OptionIndex, ResponseTimeMs));
742→            return;
743→        }
744→        FPlatformProcess::Sleep(0.1f);
745→    }
746→
747→    BridgeLog(TEXT("ERROR: Failed to write USD answer, falling back to JSON"));
748→    SendAnswer(QuestionId, OptionIndex, ResponseTimeMs);
749→}
