752→FString UBridgeComponent::UpdateUsdaVariant(const FString& Content, const FString& VariantSetName, const FString& NewValue)
753→{
754→    // Simple string replacement for variant - more reliable than regex
755→    FString SearchPattern = FString::Printf(TEXT("string %s = \""), *VariantSetName);
756→    int32 StartIdx = Content.Find(SearchPattern);
757→    if (StartIdx == INDEX_NONE)
758→    {
759→        return Content;
760→    }
761→
762→    StartIdx += SearchPattern.Len();
763→    int32 EndIdx = Content.Find(TEXT("\""), ESearchCase::CaseSensitive, ESearchDir::FromStart, StartIdx);
764→    if (EndIdx == INDEX_NONE)
765→    {
766→        return Content;
767→    }
768→
769→    // Build new content
770→    FString Result = Content.Left(StartIdx) + NewValue + Content.Mid(EndIdx);
771→    return Result;
772→}
