774→
775→FString UBridgeComponent::UpdateUsdaAttribute(const FString& Content, const FString& PrimName, const FString& AttrName, const FString& NewValue, bool bIsString)
776→{
777→    // Find attribute pattern and replace value
778→    // For string: string attrName = "value"
779→    // For numeric: int/float/double attrName = value
780→
781→    FString Result = Content;
782→
783→    if (bIsString)
784→    {
785→        // Find: string attrName = "..."
786→        FString SearchPattern = FString::Printf(TEXT("string %s = \""), *AttrName);
787→        int32 StartIdx = Result.Find(SearchPattern);
788→        if (StartIdx != INDEX_NONE)
789→        {
790→            StartIdx += SearchPattern.Len();
791→            int32 EndIdx = Result.Find(TEXT("\""), ESearchCase::CaseSensitive, ESearchDir::FromStart, StartIdx);
792→            if (EndIdx != INDEX_NONE)
793→            {
794→                FString EscapedValue = NewValue.Replace(TEXT("\\"), TEXT("\\\\")).Replace(TEXT("\""), TEXT("\\\""));
795→                Result = Result.Left(StartIdx) + EscapedValue + Result.Mid(EndIdx);
796→            }
797→        }
798→    }
799→    else
800→    {
801→        // Find numeric attributes: int/float/double attrName = value
802→        TArray<FString> TypePrefixes = { TEXT("int"), TEXT("float"), TEXT("double"), TEXT("bool") };
803→
804→        for (const FString& TypePrefix : TypePrefixes)
805→        {
806→            FString SearchPattern = FString::Printf(TEXT("%s %s = "), *TypePrefix, *AttrName);
807→            int32 StartIdx = Result.Find(SearchPattern);
808→            if (StartIdx != INDEX_NONE)
809→            {
810→                StartIdx += SearchPattern.Len();
811→                // Find end of value (newline or space or semicolon)
812→                int32 EndIdx = StartIdx;
813→                while (EndIdx < Result.Len())
814→                {
815→                    TCHAR C = Result[EndIdx];
816→                    if (C == '\n' || C == '\r' || C == ';' || C == ' ' || C == '\t')
817→                    {
818→                        break;
819→                    }
820→                    EndIdx++;
821→                }
822→                Result = Result.Left(StartIdx) + NewValue + Result.Mid(EndIdx);
823→                break;
824→            }
825→        }
826→    }
827→
828→    return Result;
829→}
