831→
832→void UBridgeComponent::UpdateBehavioralSignals(FString& Content, float ResponseTimeMs)
833→{
834→    // ═══════════════════════════════════════════════════════════════════════════════
835→    // THINKINGMACHINES [He2025] BATCH-INVARIANCE COMPLIANT
836→    // Same signals → Same routing → Same behavior
837→    // FIXED thresholds ensure deterministic expert selection regardless of load
838→    // ═══════════════════════════════════════════════════════════════════════════════
839→
840→    // PHASE 1: DETECT - Collect signals
841→    ResponseTimes.Add(ResponseTimeMs);
842→
843→    // Calculate average response time (FIXED algorithm - sum/count)
844→    float TotalTime = 0.0f;
845→    for (float Time : ResponseTimes)
846→    {
847→        TotalTime += Time;
848→    }
849→    float AvgResponseTime = ResponseTimes.Num() > 0 ? TotalTime / ResponseTimes.Num() : 0.0f;
850→
851→    // FIXED THRESHOLDS (batch-invariant - same across all sessions)
852→    const float HESITATION_THRESHOLD_MS = 10000.0f;   // 10 seconds
853→    const float RAPID_CLICK_THRESHOLD_MS = 500.0f;    // 0.5 seconds
854→    const float DEPLETED_AVG_THRESHOLD_MS = 15000.0f; // 15 seconds average
855→    const int32 HESITATION_COUNT_THRESHOLD = 2;
856→    const int32 RAPID_CLICK_COUNT_THRESHOLD = 3;
857→
858→    // Detect hesitation
859→    bool bLongHesitation = ResponseTimeMs > HESITATION_THRESHOLD_MS;
860→    if (bLongHesitation)
861→    {
862→        HesitationCount++;
863→    }
864→
865→    // Detect rapid clicking
866→    bool bRapidClick = ResponseTimeMs < RAPID_CLICK_THRESHOLD_MS && ResponseTimes.Num() > 1;
867→    if (bRapidClick)
868→    {
869→        RapidClickCount++;
870→    }
